Here is a simple C++ class implementation for a `Point` in two-dimensional space:

```cpp
#include <iostream>

class Point {
private:
    double x;
    double y;

public:
    // Constructor
    Point(double xVal = 0.0, double yVal = 0.0) : x(xVal), y(yVal) {}

    // Getters
    double getX() const { return x; }
    double getY() const { return y; }

    // Setters
    void setX(double xVal) { x = xVal; }
    void setY(double yVal) { y = yVal; }

    // Overload the << operator for easy printing
    friend std::ostream& operator<<(std::ostream& os, const Point& p) {
        os << "(" << p.x << ", " << p.y << ")";
        return os;
    }

    // Method to calculate distance from origin
    double distanceFromOrigin() const {
        return std::sqrt(x * x + y * y);
    }
};

int main() {
    Point p1(3.0, 4.0);
    std::cout << "Point p1: " << p1 << std::endl;
    std::cout << "Distance from origin: " << p1.distanceFromOrigin() << std::endl;

    return 0;
}
```
